# Make all m2 changes in arrow.py
with open("arrow/arrow.py", "r") as f:
    content = f.read()

# Change 1: __init__ default tz (line 167)
content = content.replace(
    "        if tzinfo is None:\n            tzinfo = dateutil_tz.tzutc()",
    "        if tzinfo is None:\n            tzinfo = dt_timezone.utc",
    1  # Only replace first occurrence
)

