old_init_str = """        elif isinstance(tzinfo, str):
            tzinfo = parser.TzinfoParser.parse(tzinfo)"""
new_init_str = """        elif isinstance(tzinfo, str):
            try:
                tzinfo = ZoneInfo(tzinfo)
            except Exception:
                tzinfo = parser.TzinfoParser.parse(tzinfo)"""
content = content.replace(old_init_str, new_init_str, 1)

# Change 3: now() local tz (line 202)
