old_fromts = """        if tzinfo is None:
            tzinfo = dateutil_tz.tzlocal()
        elif isinstance(tzinfo, str):
            tzinfo = parser.TzinfoParser.parse(tzinfo)"""
new_fromts = """        if tzinfo is None:
            tzinfo = dt_datetime.now().astimezone().tzinfo
        elif isinstance(tzinfo, str):
            try:
                tzinfo = ZoneInfo(tzinfo)
            except Exception:
                tzinfo = parser.TzinfoParser.parse(tzinfo)"""
content = content.replace(old_fromts, new_fromts, 1)

