old_to = """        if not isinstance(tz, dt_tzinfo):
            tz = parser.TzinfoParser.parse(tz)"""
new_to = """        if not isinstance(tz, dt_tzinfo):
            try:
                tz = ZoneInfo(tz)
            except Exception:
                tz = parser.TzinfoParser.parse(tz)"""
content = content.replace(old_to, new_to, 1)

# Change 6: _get_tzinfo() method (lines 1792-1800)
old_get_tzinfo = """    @staticmethod
    def _get_tzinfo(tz_expr: Optional[TZ_EXPR]) -> dt_tzinfo:
        \"\"\"Get normalized tzinfo object from various inputs.\"\"\"
        if tz_expr is None:
            return dateutil_tz.tzutc()
        if isinstance(tz_expr, dt_tzinfo):
            return tz_expr
        else:
            try:
                return parser.TzinfoParser.parse(tz_expr)
